  /**
   * Test AccountNetMessage {@link AccountNetMessage#getDescriptor()}.
   * <p>
   * Method under test: {@link AccountNetMessage#getDescriptor()}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"Descriptors.Descriptor AccountNetMessage.getDescriptor()"})
  public void testAccountNetMessageGetDescriptor() {
    // Arrange and Act
    Descriptor actualDescriptor = AccountNetMessage.getDescriptor();

    // Assert
    assertEquals("AccountNetMessage", actualDescriptor.getName());
    assertEquals("protocol.AccountNetMessage", actualDescriptor.getFullName());
    assertNull(actualDescriptor.getContainingType());
    assertEquals(2, actualDescriptor.getNestedTypes().size());
    assertEquals(30, actualDescriptor.getIndex());
    assertEquals(8, actualDescriptor.getFields().size());
    assertFalse(actualDescriptor.isExtendable());
    assertTrue(actualDescriptor.getEnumTypes().isEmpty());
    assertTrue(actualDescriptor.getExtensions().isEmpty());
    assertTrue(actualDescriptor.getOneofs().isEmpty());
    assertTrue(actualDescriptor.getRealOneofs().isEmpty());
  }

