  /**
   * Test AccountNetMessage {@link AccountNetMessage#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link AccountNetMessage#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"AccountNetMessage AccountNetMessage.parseDelimitedFrom(InputStream)"})
  public void testAccountNetMessageParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    AccountNetMessage actualParseDelimitedFromResult = AccountNetMessage.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getAssetNetLimitCount());
    assertEquals(0, actualParseDelimitedFromResult.getAssetNetUsedCount());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0L, actualParseDelimitedFromResult.getFreeNetLimit());
    assertEquals(0L, actualParseDelimitedFromResult.getFreeNetUsed());
    assertEquals(0L, actualParseDelimitedFromResult.getNetLimit());
    assertEquals(0L, actualParseDelimitedFromResult.getNetUsed());
    assertEquals(0L, actualParseDelimitedFromResult.getTotalNetLimit());
    assertEquals(0L, actualParseDelimitedFromResult.getTotalNetWeight());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAssetNetLimit().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAssetNetLimitMap().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAssetNetUsed().isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAssetNetUsedMap().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

