  public void testBlockIncrementalMerkleTreeParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{2, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    BlockIncrementalMerkleTree actualParseDelimitedFromResult = BlockIncrementalMerkleTree.parseDelimitedFrom(input);

    // Assert
    assertEquals(2, actualParseDelimitedFromResult.getUnknownFields().getSerializedSize());
    assertEquals(2, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[5];
    assertEquals(5, input.read(byteArray));
    BlockIncrementalMerkleTree defaultInstanceForType = actualParseDelimitedFromResult.getDefaultInstanceForType();
    assertSame(defaultInstanceForType.getDefaultInstanceForType(), defaultInstanceForType.getDefaultInstanceForType());
    IncrementalMerkleTree merkleTree = actualParseDelimitedFromResult.getMerkleTree();
    assertSame(merkleTree, defaultInstanceForType.getMerkleTree());
    assertSame(merkleTree, defaultInstanceForType.getMerkleTreeOrBuilder());
    assertSame(merkleTree, actualParseDelimitedFromResult.getMerkleTreeOrBuilder());
    assertSame(merkleTree, merkleTree.getDefaultInstanceForType());
    assertArrayEquals("XAXAX".getBytes("UTF-8"), byteArray);
  }

