  /**
   * Test NoteParameters {@link NoteParameters#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link NoteParameters#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"NoteParameters NoteParameters.parseDelimitedFrom(InputStream)"})
  public void testNoteParametersParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    NoteParameters actualParseDelimitedFromResult = NoteParameters.parseDelimitedFrom(input);

    // Assert
    UnknownFieldSet unknownFields = actualParseDelimitedFromResult.getUnknownFields();
    assertEquals(0, unknownFields.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(5, actualParseDelimitedFromResult.getDescriptorForType().getFields().size());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    Note note = actualParseDelimitedFromResult.getNote();
    assertSame(unknownFields, note.getUnknownFields());
    assertSame(unknownFields, unknownFields.getDefaultInstanceForType());
    assertSame(note, note.getDefaultInstanceForType());
    assertSame(note, actualParseDelimitedFromResult.getNoteOrBuilder());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

