  /**
   * Test OvkDecryptTRC20Parameters {@link OvkDecryptTRC20Parameters#getEventsList()}.
   * <p>
   * Method under test: {@link OvkDecryptTRC20Parameters#getEventsList()}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"ProtocolStringList OvkDecryptTRC20Parameters.getEventsList()"})
  public void testOvkDecryptTRC20ParametersGetEventsList() {
    // Arrange
    OvkDecryptTRC20Parameters defaultInstance = OvkDecryptTRC20Parameters.getDefaultInstance();

    // Act
    ProtocolStringList actualEventsList = defaultInstance.getEventsList();

    // Assert
    assertTrue(actualEventsList.isEmpty());
    LazyStringList lazyStringList = ((LazyStringArrayList) actualEventsList).EMPTY;
    Descriptor descriptorForType = defaultInstance.getDescriptorForType();
    DescriptorProto toProtoResult = descriptorForType.toProto();
    DescriptorProto defaultInstanceForType = toProtoResult.getDefaultInstanceForType();
    assertEquals(lazyStringList, defaultInstanceForType.findInitializationErrors());
    assertEquals(lazyStringList, descriptorForType.getOptions().getFeatures().findInitializationErrors());
    Descriptor descriptorForType2 = toProtoResult.getDescriptorForType();
    assertEquals(lazyStringList, descriptorForType2.getEnumTypes());
    assertEquals(lazyStringList, descriptorForType2.getExtensions());
    assertEquals(lazyStringList, descriptorForType2.getOneofs());
    assertEquals(lazyStringList, descriptorForType2.getRealOneofs());
    assertSame(lazyStringList, defaultInstanceForType.getReservedNameList());
    assertSame(lazyStringList, toProtoResult.getReservedNameList());
    assertSame(lazyStringList, actualEventsList);
  }

