  /**
   * Test PrivateParameters {@link PrivateParameters#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link PrivateParameters#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"PrivateParameters PrivateParameters.parseDelimitedFrom(InputStream)"})
  public void testPrivateParametersParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{0, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    PrivateParameters actualParseDelimitedFromResult = PrivateParameters.parseDelimitedFrom(input);

    // Assert
    assertEquals("", actualParseDelimitedFromResult.getInitializationErrorString());
    assertEquals(0, actualParseDelimitedFromResult.getSerializedSize());
    assertEquals(0, actualParseDelimitedFromResult.getShieldedReceivesCount());
    assertEquals(0, actualParseDelimitedFromResult.getShieldedSpendsCount());
    assertEquals(0L, actualParseDelimitedFromResult.getFromAmount());
    assertEquals(0L, actualParseDelimitedFromResult.getTimeout());
    assertEquals(0L, actualParseDelimitedFromResult.getToAmount());
    byte[] byteArray = new byte[7];
    assertEquals(7, input.read(byteArray));
    assertTrue(actualParseDelimitedFromResult.findInitializationErrors().isEmpty());
    List<ReceiveNote> shieldedReceivesList = actualParseDelimitedFromResult.getShieldedReceivesList();
    assertTrue(shieldedReceivesList.isEmpty());
    assertTrue(actualParseDelimitedFromResult.getAllFields().isEmpty());
    assertTrue(actualParseDelimitedFromResult.isInitialized());
    assertEquals(actualParseDelimitedFromResult, actualParseDelimitedFromResult.getDefaultInstanceForType());
    assertSame(shieldedReceivesList, actualParseDelimitedFromResult.getShieldedReceivesOrBuilderList());
    assertSame(shieldedReceivesList, actualParseDelimitedFromResult.getShieldedSpendsList());
    assertSame(shieldedReceivesList, actualParseDelimitedFromResult.getShieldedSpendsOrBuilderList());
    assertArrayEquals("XAXAXAX".getBytes("UTF-8"), byteArray);
  }

