  /**
   * Test ShieldedAddressInfo {@link ShieldedAddressInfo#parseFrom(byte[], ExtensionRegistryLite)} with {@code byte[]}, {@code ExtensionRegistryLite}.
   * <p>
   * Method under test: {@link ShieldedAddressInfo#parseFrom(byte[], ExtensionRegistryLite)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"ShieldedAddressInfo ShieldedAddressInfo.parseFrom(byte[], ExtensionRegistryLite)"})
  public void testShieldedAddressInfoParseFromWithByteExtensionRegistryLite() throws InvalidProtocolBufferException {
    // Arrange and Act
    ShieldedAddressInfo actualParseFromResult = ShieldedAddressInfo.parseFrom(new byte[]{},
        ExtensionRegistryLite.getEmptyRegistry());

    // Assert
    assertEquals(0, actualParseFromResult.getSerializedSize());
    Map<FieldDescriptor, Object> allFields = actualParseFromResult.getAllFields();
    assertTrue(allFields.isEmpty());
    Descriptor descriptorForType = actualParseFromResult.getDescriptorForType();
    assertEquals(allFields, descriptorForType.toProto().getDefaultInstanceForType().getAllFields());
    FileDescriptor file = descriptorForType.getFile();
    FileDescriptorProto toProtoResult = file.toProto();
    assertEquals(allFields, toProtoResult.getDefaultInstanceForType().getAllFields());
    SourceCodeInfo sourceCodeInfo = toProtoResult.getSourceCodeInfo();
    assertEquals(allFields, sourceCodeInfo.getAllFields());
    FileOptions defaultInstanceForType = file.getOptions().getDefaultInstanceForType();
    assertEquals(allFields, defaultInstanceForType.getAllFields());
    FeatureSet features = descriptorForType.getOptions().getFeatures();
    assertEquals(allFields, features.getAllFields());
    List<FieldDescriptor> fields = descriptorForType.getFields();
    assertEquals(ShieldedAddressInfo.PAYMENT_ADDRESS_FIELD_NUMBER, fields.size());
    FieldOptions options = fields.get(0).getOptions();
    assertEquals(allFields, options.getAllFields());
    assertEquals(allFields, defaultInstanceForType.getAllFieldsRaw());
    assertEquals(allFields, features.getAllFieldsRaw());
    assertEquals(allFields, options.getAllFieldsRaw());
    assertEquals(actualParseFromResult, actualParseFromResult.getDefaultInstanceForType());
    assertSame(sourceCodeInfo, sourceCodeInfo.getDefaultInstanceForType());
  }

