  @MethodsUnderTest({"SpendNote SpendNote.parseFrom(InputStream)"})
  public void testSpendNoteParseFromWithInputStream() throws IOException {
    // Arrange and Act
    SpendNote actualParseFromResult = SpendNote.parseFrom(new ByteArrayInputStream(new byte[]{}));

    // Assert
    assertEquals(actualParseFromResult, actualParseFromResult.getDefaultInstanceForType());
    UnknownFieldSet unknownFields = actualParseFromResult.getUnknownFields();
    Note note = actualParseFromResult.getNote();
    assertSame(unknownFields, note.getUnknownFields());
    IncrementalMerkleVoucher voucher = actualParseFromResult.getVoucher();
    assertSame(unknownFields, voucher.getUnknownFields());
    assertSame(unknownFields, unknownFields.getDefaultInstanceForType());
    assertSame(note, note.getDefaultInstanceForType());
    assertSame(note, actualParseFromResult.getNoteOrBuilder());
    assertSame(voucher, actualParseFromResult.getVoucherOrBuilder());
    assertSame(voucher, voucher.getDefaultInstanceForType());
  }

