  /**
   * Test TimePaginatedMessage {@link TimePaginatedMessage#parseDelimitedFrom(InputStream)} with {@code input}.
   * <p>
   * Method under test: {@link TimePaginatedMessage#parseDelimitedFrom(InputStream)}
   */
  @Test
  @Category(MaintainedByDiffblue.class)
  @MethodsUnderTest({"TimePaginatedMessage TimePaginatedMessage.parseDelimitedFrom(InputStream)"})
  public void testTimePaginatedMessageParseDelimitedFromWithInput() throws IOException {
    // Arrange
    ByteArrayInputStream input = new ByteArrayInputStream(new byte[]{2, 'X', 'A', 'X', 'A', 'X', 'A', 'X'});

    // Act
    TimePaginatedMessage actualParseDelimitedFromResult = TimePaginatedMessage.parseDelimitedFrom(input);

    // Assert
    assertEquals(2, actualParseDelimitedFromResult.getUnknownFields().getSerializedSize());
    assertEquals(2, actualParseDelimitedFromResult.getSerializedSize());
    byte[] byteArray = new byte[5];
    assertEquals(5, input.read(byteArray));
    TimePaginatedMessage defaultInstanceForType = actualParseDelimitedFromResult.getDefaultInstanceForType();
    assertSame(defaultInstanceForType.getDefaultInstanceForType(), defaultInstanceForType.getDefaultInstanceForType());
    TimeMessage timeMessage = actualParseDelimitedFromResult.getTimeMessage();
    assertSame(timeMessage, timeMessage.getDefaultInstanceForType());
    assertSame(timeMessage, defaultInstanceForType.getTimeMessage());
    assertSame(timeMessage, defaultInstanceForType.getTimeMessageOrBuilder());
    assertSame(timeMessage, actualParseDelimitedFromResult.getTimeMessageOrBuilder());
    assertArrayEquals("XAXAX".getBytes("UTF-8"), byteArray);
  }

